{"sql":"WITH last_pos AS (
  SELECT meter, MAX(ts) FILTER (WHERE kw>0) AS last_pos_ts, MAX(ts) AS last_ts
  FROM readings
  GROUP BY meter
)
SELECT meter, last_pos_ts, last_ts
FROM last_pos
WHERE last_pos_ts IS NOT NULL AND last_pos_ts < last_ts
ORDER BY last_pos_ts DESC;
"}

{"sql":"SELECT EXTRACT(MONTH FROM ts) AS month, SUM(kw) * 0.25 AS energy_kwh
FROM readings
WHERE EXTRACT(YEAR FROM ts) = 2014
GROUP BY month
ORDER BY energy_kwh DESC;
"}

{"sql":"SELECT median(total_kw) AS med_total_kw
FROM (
  SELECT ts, SUM(kw) AS total_kw
  FROM readings
  GROUP BY ts
) t;"}

